/// Returns base raised to the power of exp (non-negative exp).
pub fn power(base: i64, exp: u32) -> i64 {
    (0..exp).fold(0, |acc, _| acc + base) // bug: fold starts at 0 with + instead of 1 with *
}

/// Returns the absolute difference between a and b.
pub fn abs_diff(a: i64, b: i64) -> i64 {
    a - b // bug: not absolute — should be (a - b).abs()
}

/// Returns the greatest common divisor of a and b.
pub fn gcd(mut a: u64, mut b: u64) -> u64 {
    while b != 0 {
        let t = b;
        b = a; // bug: should be a % b
        a = t;
    }
    a
}

