use calculator::{power, abs_diff, gcd};

#[test]
fn test_power() {
    assert_eq!(power(2, 10), 1024);
    assert_eq!(power(3, 0), 1);
    assert_eq!(power(5, 1), 5);
}

#[test]
fn test_abs_diff() {
    assert_eq!(abs_diff(10, 3), 7);
    assert_eq!(abs_diff(3, 10), 7);
    assert_eq!(abs_diff(5, 5), 0);
}

#[test]
fn test_gcd() {
    assert_eq!(gcd(48, 18), 6);
    assert_eq!(gcd(0, 5), 5);
    assert_eq!(gcd(7, 7), 7);
}
